<!doctype html>
<html lang="en">
<head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>{{ $siteContent->title }} preview - Revision {{ $revision->revision_number }}</title><style>body{font:16px/1.5 system-ui;margin:0;color:#171717;background:#f5f3ee}.banner{padding:12px 24px;background:#251f1a;color:#fff}.wrap{max-width:1100px;margin:auto;padding:32px}.card{background:#fff;padding:20px;border:1px solid #ddd;border-radius:10px}nav ul{display:flex;flex-wrap:wrap;gap:20px;list-style:none;padding:0}.announcement{text-align:center;padding:16px;background:#e9dfce}.footer-groups{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:20px}@media(max-width:600px){.wrap{padding:18px}nav ul{display:block}}</style></head>
<body><div class="banner">Secure {{ str_replace('_', ' ', $siteContent->type) }} preview - Revision {{ $revision->revision_number }} - Public storefront projection is not active yet.</div><main class="wrap">
