@elseif($siteContent->type === 'site_profile')<section class="card"><h1>{{ data_get($revision->payload, 'brand.name') }}</h1><p>{{ data_get($revision->payload, 'brand.description') }}</p><h2>Contact</h2><p>{{ data_get($revision->payload, 'contact.email') }}<br>{{ data_get($revision->payload, 'contact.telephone') }}<br>{{ data_get($revision->payload, 'contact.address') }}</p><h2>Social links</h2><ul>@foreach(data_get($revision->payload, 'social_links', []) as $social)<li>{{ $social['label'] }}</li>@endforeach</ul><footer><p>{{ data_get($revision->payload, 'footer.description') }}</p><p>{{ data_get($revision->payload, 'footer.copyright') }}</p></footer></section>
